class _UniffiFfiConverterBytes(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative byte string length")
        return buf.read(size)

    @staticmethod
    def check_lower(value):
        try:
            memoryview(value)
        except TypeError:
            raise TypeError("a bytes-like object is required, not {!r}".format(type(value).__name__))

    @staticmethod
    def write(value, buf):
        buf.write_i32(len(value))
        buf.write(value)

@dataclass
class Assertion:
    """
    A WebAuthn assertion as the platform returns it; `prf` says whether a PRF output was written.
"""
    def __init__(self, *, credential_id:bytes, authenticator_data:bytes, client_data_json:bytes, signature:bytes, prf:bool):
        self.credential_id = credential_id
        self.authenticator_data = authenticator_data
        self.client_data_json = client_data_json
        self.signature = signature
        self.prf = prf
        
        

    
    def __str__(self):
        return "Assertion(credential_id={}, authenticator_data={}, client_data_json={}, signature={}, prf={})".format(self.credential_id, self.authenticator_data, self.client_data_json, self.signature, self.prf)
    def __eq__(self, other):
        if self.credential_id != other.credential_id:
            return False
        if self.authenticator_data != other.authenticator_data:
            return False
        if self.client_data_json != other.client_data_json:
            return False
        if self.signature != other.signature:
            return False
        if self.prf != other.prf:
            return False
        return True

class _UniffiFfiConverterTypeAssertion(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        return Assertion(
            credential_id=_UniffiFfiConverterBytes.read(buf),
            authenticator_data=_UniffiFfiConverterBytes.read(buf),
            client_data_json=_UniffiFfiConverterBytes.read(buf),
            signature=_UniffiFfiConverterBytes.read(buf),
            prf=_UniffiFfiConverterBoolean.read(buf),
        )

    @staticmethod
    def check_lower(value):
        _UniffiFfiConverterBytes.check_lower(value.credential_id)
        _UniffiFfiConverterBytes.check_lower(value.authenticator_data)
        _UniffiFfiConverterBytes.check_lower(value.client_data_json)
        _UniffiFfiConverterBytes.check_lower(value.signature)
        _UniffiFfiConverterBoolean.check_lower(value.prf)

    @staticmethod
    def write(value, buf):
        _UniffiFfiConverterBytes.write(value.credential_id, buf)
        _UniffiFfiConverterBytes.write(value.authenticator_data, buf)
        _UniffiFfiConverterBytes.write(value.client_data_json, buf)
        _UniffiFfiConverterBytes.write(value.signature, buf)
        _UniffiFfiConverterBoolean.write(value.prf, buf)

class _UniffiFfiConverterSequenceBytes(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterBytes.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterBytes.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterBytes.read(buf) for i in range(count)
        ]

class _UniffiFfiConverterOptionalBytes(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterBytes.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterBytes.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterBytes.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")

