class Family(enum.Enum):
    """
    A chain family (the `scaas-rpc` readers'). Hedera is `Evm` with its chain id.
"""
    
    EVM = 0
    
    SOROBAN = 1
    
    SOLANA = 2
    
    NEAR = 3
    
    ALGORAND = 4
    
