class EndpointAuth:
    def __init__(self):
        raise RuntimeError("EndpointAuth cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class BEARER:
        
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

    
            
            

    
        def __str__(self):
            return f"EndpointAuth.BEARER{self._values!r}"
        def __eq__(self, other):
            if not isinstance(other, EndpointAuth):
                return NotImplemented
            if not other.is_BEARER():
                return False
            return self._values == other._values

    @dataclass
    class HMAC:
        
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

    
            
            

    
        def __str__(self):
            return f"EndpointAuth.HMAC{self._values!r}"
        def __eq__(self, other):
            if not isinstance(other, EndpointAuth):
                return NotImplemented
            if not other.is_HMAC():
                return False
            return self._values == other._values

    @dataclass
    class HEADER:
        
        def __init__(self, name:str, value:Secret):
            self.name = name
            
            
            self.value = value
            
            
            pass

    
            
            
    
        def __str__(self):
            return "EndpointAuth.HEADER(name={}, value={})".format(self.name, self.value)
        def __eq__(self, other):
            if not isinstance(other, EndpointAuth):
                return NotImplemented
            if not other.is_HEADER():
                return False
            if self.name != other.name:
                return False
            if self.value != other.value:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_BEARER(self) -> bool:
        return isinstance(self, EndpointAuth.BEARER)
    def is_bearer(self) -> bool:
        return isinstance(self, EndpointAuth.BEARER)
    def is_HMAC(self) -> bool:
        return isinstance(self, EndpointAuth.HMAC)
    def is_hmac(self) -> bool:
        return isinstance(self, EndpointAuth.HMAC)
    def is_HEADER(self) -> bool:
        return isinstance(self, EndpointAuth.HEADER)
    def is_header(self) -> bool:
        return isinstance(self, EndpointAuth.HEADER)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
EndpointAuth.BEARER = type("EndpointAuth.BEARER", (EndpointAuth.BEARER, EndpointAuth,), {})  # type: ignore
EndpointAuth.HMAC = type("EndpointAuth.HMAC", (EndpointAuth.HMAC, EndpointAuth,), {})  # type: ignore
EndpointAuth.HEADER = type("EndpointAuth.HEADER", (EndpointAuth.HEADER, EndpointAuth,), {})  # type: ignore




class _UniffiFfiConverterTypeEndpointAuth(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return EndpointAuth.BEARER(
                _UniffiFfiConverterTypeSecret.read(buf),
            )
        if variant == 2:
            return EndpointAuth.HMAC(
                _UniffiFfiConverterTypeSecret.read(buf),
            )
        if variant == 3:
            return EndpointAuth.HEADER(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterTypeSecret.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_BEARER():
            _UniffiFfiConverterTypeSecret.check_lower(value._values[0])
            return
        if value.is_HMAC():
            _UniffiFfiConverterTypeSecret.check_lower(value._values[0])
            return
        if value.is_HEADER():
            _UniffiFfiConverterString.check_lower(value.name)
            _UniffiFfiConverterTypeSecret.check_lower(value.value)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_BEARER():
            buf.write_i32(1)
            _UniffiFfiConverterTypeSecret.write(value._values[0], buf)
        if value.is_HMAC():
            buf.write_i32(2)
            _UniffiFfiConverterTypeSecret.write(value._values[0], buf)
        if value.is_HEADER():
            buf.write_i32(3)
            _UniffiFfiConverterString.write(value.name, buf)
            _UniffiFfiConverterTypeSecret.write(value.value, buf)



