class SecretBytesProtocol(typing.Protocol):
    
    pass

class SecretBytes(SecretBytesProtocol):
    
    _handle: ctypes.c_uint64
    
    def __init__(self, *args, **kwargs):
        raise ValueError("This class has no default constructor")

    def __del__(self):
        # In case of partial initialization of instances.
        handle = getattr(self, "_handle", None)
        if handle is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_scaas_sdk_fn_free_secretbytes, handle)

    def _uniffi_clone_handle(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_scaas_sdk_fn_clone_secretbytes, self._handle)

    # Used by alternative constructors or any methods which return this type.
    @classmethod
    def _uniffi_make_instance(cls, handle):
        # Lightly yucky way to bypass the usual __init__ logic
        # and just create a new instance with the required handle.
        inst = cls.__new__(cls)
        inst._handle = handle
        return inst





class _UniffiFfiConverterTypeSecretBytes:
    @staticmethod
    def lift(value: int) -> SecretBytes:
        return SecretBytes._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: SecretBytes):
        if not isinstance(value, SecretBytes):
            raise TypeError("Expected SecretBytes instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: SecretBytes) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> SecretBytes:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: SecretBytes, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

