class _UniffiFfiConverterTypeAllowOpaqueCall:
    @staticmethod
    def write(value, buf):
        _UniffiFfiConverterBoolean.write(value, buf)

    @staticmethod
    def read(buf):
        return _UniffiFfiConverterBoolean.read(buf)

    @staticmethod
    def lift(value):
        return _UniffiFfiConverterBoolean.lift(value)

    @staticmethod
    def check_lower(value):
        return _UniffiFfiConverterBoolean.check_lower(value)

    @staticmethod
    def lower(value):
        return _UniffiFfiConverterBoolean.lower(value)


AllowOpaqueCall = bool

class _UniffiFfiConverterOptionalTypeAllowOpaqueCall(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeAllowOpaqueCall.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeAllowOpaqueCall.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeAllowOpaqueCall.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")






class ExecuteCall:
    """
    A mandate wallet's call (spec §13.2): decoded, or opaque under the marker.
"""
    def __init__(self):
        raise RuntimeError("ExecuteCall cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class TRANSFER:
        """
        an ERC-20 `transfer(to, amount)` of `token` held by the wallet
"""
        
        def __init__(self, token:str, to:str, amount:str):
            self.token = token
            
            
            self.to = to
            
            
            self.amount = amount
            
            
            pass

    
            
            
    
        def __str__(self):
            return "ExecuteCall.TRANSFER(token={}, to={}, amount={})".format(self.token, self.to, self.amount)
        def __eq__(self, other):
            if not isinstance(other, ExecuteCall):
                return NotImplemented
            if not other.is_TRANSFER():
                return False
            if self.token != other.token:
                return False
            if self.to != other.to:
                return False
            if self.amount != other.amount:
                return False
            return True

    @dataclass
    class OPAQUE:
        """
        any other call: `OpaqueCallRefused` without the marker
"""
        
        def __init__(self, target:str, value:str, data:str, allow:typing.Optional[AllowOpaqueCall]):
            self.target = target
            
            
            self.value = value
            
            
            self.data = data
            
            
            self.allow = allow
            
            
            pass

    
            
            
    
        def __str__(self):
            return "ExecuteCall.OPAQUE(target={}, value={}, data={}, allow={})".format(self.target, self.value, self.data, self.allow)
        def __eq__(self, other):
            if not isinstance(other, ExecuteCall):
                return NotImplemented
            if not other.is_OPAQUE():
                return False
            if self.target != other.target:
                return False
            if self.value != other.value:
                return False
            if self.data != other.data:
                return False
            if self.allow != other.allow:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_TRANSFER(self) -> bool:
        return isinstance(self, ExecuteCall.TRANSFER)
    def is_transfer(self) -> bool:
        return isinstance(self, ExecuteCall.TRANSFER)
    def is_OPAQUE(self) -> bool:
        return isinstance(self, ExecuteCall.OPAQUE)
    def is_opaque(self) -> bool:
        return isinstance(self, ExecuteCall.OPAQUE)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
ExecuteCall.TRANSFER = type("ExecuteCall.TRANSFER", (ExecuteCall.TRANSFER, ExecuteCall,), {})  # type: ignore
ExecuteCall.OPAQUE = type("ExecuteCall.OPAQUE", (ExecuteCall.OPAQUE, ExecuteCall,), {})  # type: ignore




class _UniffiFfiConverterTypeExecuteCall(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ExecuteCall.TRANSFER(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 2:
            return ExecuteCall.OPAQUE(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterOptionalTypeAllowOpaqueCall.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_TRANSFER():
            _UniffiFfiConverterString.check_lower(value.token)
            _UniffiFfiConverterString.check_lower(value.to)
            _UniffiFfiConverterString.check_lower(value.amount)
            return
        if value.is_OPAQUE():
            _UniffiFfiConverterString.check_lower(value.target)
            _UniffiFfiConverterString.check_lower(value.value)
            _UniffiFfiConverterString.check_lower(value.data)
            _UniffiFfiConverterOptionalTypeAllowOpaqueCall.check_lower(value.allow)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_TRANSFER():
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.token, buf)
            _UniffiFfiConverterString.write(value.to, buf)
            _UniffiFfiConverterString.write(value.amount, buf)
        if value.is_OPAQUE():
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.target, buf)
            _UniffiFfiConverterString.write(value.value, buf)
            _UniffiFfiConverterString.write(value.data, buf)
            _UniffiFfiConverterOptionalTypeAllowOpaqueCall.write(value.allow, buf)



