class GasFrom:
    """
    Where a part of a quote's gas figure came from (owner 2026-11-19), so the app and the operator see a figure not measured on
    the chain.
"""
    def __init__(self):
        raise RuntimeError("GasFrom cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class CHAIN:
        """
        a row of the chain profile, measured on that chain
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "GasFrom.CHAIN()".format()
        def __eq__(self, other):
            if not isinstance(other, GasFrom):
                return NotImplemented
            if not other.is_CHAIN():
                return False
            return True

    @dataclass
    class MODULE:
        """
        a row of the named module table, the profile having opted in
"""
        
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

    
            
            

    
        def __str__(self):
            return f"GasFrom.MODULE{self._values!r}"
        def __eq__(self, other):
            if not isinstance(other, GasFrom):
                return NotImplemented
            if not other.is_MODULE():
                return False
            return self._values == other._values

    @dataclass
    class REFERENCE:
        """
        a row of the SCaaS reference table, the profile having opted in; not measured on this chain
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "GasFrom.REFERENCE()".format()
        def __eq__(self, other):
            if not isinstance(other, GasFrom):
                return NotImplemented
            if not other.is_REFERENCE():
                return False
            return True

    @dataclass
    class APP:
        """
        the figure the app passed on the call
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "GasFrom.APP()".format()
        def __eq__(self, other):
            if not isinstance(other, GasFrom):
                return NotImplemented
            if not other.is_APP():
                return False
            return True

    @dataclass
    class ESTIMATE:
        """
        a native send's own estimate (or 21,000 for a plain transfer to an account without code)
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "GasFrom.ESTIMATE()".format()
        def __eq__(self, other):
            if not isinstance(other, GasFrom):
                return NotImplemented
            if not other.is_ESTIMATE():
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_CHAIN(self) -> bool:
        return isinstance(self, GasFrom.CHAIN)
    def is_chain(self) -> bool:
        return isinstance(self, GasFrom.CHAIN)
    def is_MODULE(self) -> bool:
        return isinstance(self, GasFrom.MODULE)
    def is_module(self) -> bool:
        return isinstance(self, GasFrom.MODULE)
    def is_REFERENCE(self) -> bool:
        return isinstance(self, GasFrom.REFERENCE)
    def is_reference(self) -> bool:
        return isinstance(self, GasFrom.REFERENCE)
    def is_APP(self) -> bool:
        return isinstance(self, GasFrom.APP)
    def is_app(self) -> bool:
        return isinstance(self, GasFrom.APP)
    def is_ESTIMATE(self) -> bool:
        return isinstance(self, GasFrom.ESTIMATE)
    def is_estimate(self) -> bool:
        return isinstance(self, GasFrom.ESTIMATE)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
GasFrom.CHAIN = type("GasFrom.CHAIN", (GasFrom.CHAIN, GasFrom,), {})  # type: ignore
GasFrom.MODULE = type("GasFrom.MODULE", (GasFrom.MODULE, GasFrom,), {})  # type: ignore
GasFrom.REFERENCE = type("GasFrom.REFERENCE", (GasFrom.REFERENCE, GasFrom,), {})  # type: ignore
GasFrom.APP = type("GasFrom.APP", (GasFrom.APP, GasFrom,), {})  # type: ignore
GasFrom.ESTIMATE = type("GasFrom.ESTIMATE", (GasFrom.ESTIMATE, GasFrom,), {})  # type: ignore




class _UniffiFfiConverterTypeGasFrom(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return GasFrom.CHAIN(
            )
        if variant == 2:
            return GasFrom.MODULE(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 3:
            return GasFrom.REFERENCE(
            )
        if variant == 4:
            return GasFrom.APP(
            )
        if variant == 5:
            return GasFrom.ESTIMATE(
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_CHAIN():
            return
        if value.is_MODULE():
            _UniffiFfiConverterString.check_lower(value._values[0])
            return
        if value.is_REFERENCE():
            return
        if value.is_APP():
            return
        if value.is_ESTIMATE():
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_CHAIN():
            buf.write_i32(1)
        if value.is_MODULE():
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value._values[0], buf)
        if value.is_REFERENCE():
            buf.write_i32(3)
        if value.is_APP():
            buf.write_i32(4)
        if value.is_ESTIMATE():
            buf.write_i32(5)



