class Source(enum.Enum):
    """
    Where a reviewed value comes from (spec §13.1).
"""
    
    SIGNED = 0
    """
    a field of the signed struct (or committed to by it, as a pay's `PayMeta`), decoded
"""
    
    REQUEST = 1
    """
    what the request named and the signed struct holds only in encrypted form (a confidential amount, recipient)
"""
    
    DERIVED = 2
    """
    what the SDK chose or read: the contract, every token or market touched with its mark
"""
    


class _UniffiFfiConverterTypeSource(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Source.SIGNED
        if variant == 2:
            return Source.REQUEST
        if variant == 3:
            return Source.DERIVED
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == Source.SIGNED:
            return
        if value == Source.REQUEST:
            return
        if value == Source.DERIVED:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == Source.SIGNED:
            buf.write_i32(1)
        if value == Source.REQUEST:
            buf.write_i32(2)
        if value == Source.DERIVED:
            buf.write_i32(3)



