class SubmitPath:
    """
    How an operation reaches the chain (spec §13.3).
"""
    def __init__(self):
        raise RuntimeError("SubmitPath cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class AUTO:
        """
        a gateway when the profile has one and the entry is one a gateway takes (door A), else a self-relay by `payer` when
        given, else `SubmitPathNone`
"""
        
        def __init__(self, payer:typing.Optional[KeyRef]):
            self.payer = payer
            
            
            pass

    
            
            
    
        def __str__(self):
            return "SubmitPath.AUTO(payer={})".format(self.payer)
        def __eq__(self, other):
            if not isinstance(other, SubmitPath):
                return NotImplemented
            if not other.is_AUTO():
                return False
            if self.payer != other.payer:
                return False
            return True

    @dataclass
    class GATEWAY:
        """
        the profile's gateways, the same body to each
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "SubmitPath.GATEWAY()".format()
        def __eq__(self, other):
            if not isinstance(other, SubmitPath):
                return NotImplemented
            if not other.is_GATEWAY():
                return False
            return True

    @dataclass
    class SELF_RELAY:
        """
        an EIP-1559 transaction from the holder's own native EVM key, which pays the gas
"""
        
        def __init__(self, payer:KeyRef):
            self.payer = payer
            
            
            pass

    
            
            
    
        def __str__(self):
            return "SubmitPath.SELF_RELAY(payer={})".format(self.payer)
        def __eq__(self, other):
            if not isinstance(other, SubmitPath):
                return NotImplemented
            if not other.is_SELF_RELAY():
                return False
            if self.payer != other.payer:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_AUTO(self) -> bool:
        return isinstance(self, SubmitPath.AUTO)
    def is_auto(self) -> bool:
        return isinstance(self, SubmitPath.AUTO)
    def is_GATEWAY(self) -> bool:
        return isinstance(self, SubmitPath.GATEWAY)
    def is_gateway(self) -> bool:
        return isinstance(self, SubmitPath.GATEWAY)
    def is_SELF_RELAY(self) -> bool:
        return isinstance(self, SubmitPath.SELF_RELAY)
    def is_self_relay(self) -> bool:
        return isinstance(self, SubmitPath.SELF_RELAY)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
SubmitPath.AUTO = type("SubmitPath.AUTO", (SubmitPath.AUTO, SubmitPath,), {})  # type: ignore
SubmitPath.GATEWAY = type("SubmitPath.GATEWAY", (SubmitPath.GATEWAY, SubmitPath,), {})  # type: ignore
SubmitPath.SELF_RELAY = type("SubmitPath.SELF_RELAY", (SubmitPath.SELF_RELAY, SubmitPath,), {})  # type: ignore




class _UniffiFfiConverterTypeSubmitPath(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return SubmitPath.AUTO(
                _UniffiFfiConverterOptionalTypeKeyRef.read(buf),
            )
        if variant == 2:
            return SubmitPath.GATEWAY(
            )
        if variant == 3:
            return SubmitPath.SELF_RELAY(
                _UniffiFfiConverterTypeKeyRef.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_AUTO():
            _UniffiFfiConverterOptionalTypeKeyRef.check_lower(value.payer)
            return
        if value.is_GATEWAY():
            return
        if value.is_SELF_RELAY():
            _UniffiFfiConverterTypeKeyRef.check_lower(value.payer)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_AUTO():
            buf.write_i32(1)
            _UniffiFfiConverterOptionalTypeKeyRef.write(value.payer, buf)
        if value.is_GATEWAY():
            buf.write_i32(2)
        if value.is_SELF_RELAY():
            buf.write_i32(3)
            _UniffiFfiConverterTypeKeyRef.write(value.payer, buf)



class _UniffiFfiConverterOptionalTypeGasSources(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeGasSources.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeGasSources.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeGasSources.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")

class _UniffiFfiConverterSequenceUInt32(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterUInt32.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterUInt32.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterUInt32.read(buf) for i in range(count)
        ]

@dataclass
class SubmitQuote:
    """
    A quote the user confirms (spec §13.3); `submit` takes exactly it. Amounts are decimal strings of wei.
"""
    def __init__(self, *, path:SubmitPath, payer:typing.Optional[str], gas_limit:int, regular_gas:int, gas:typing.Optional[int], gas_from:typing.Optional[GasSources], max_fee_per_gas:str, max_priority_fee_per_gas:str, max_cost:str, fee_to_relayer:str, gateways:typing.List[int], tx_nonce:int, tx_type:int):
        self.path = path
        self.payer = payer
        self.gas_limit = gas_limit
        self.regular_gas = regular_gas
        self.gas = gas
        self.gas_from = gas_from
        self.max_fee_per_gas = max_fee_per_gas
        self.max_priority_fee_per_gas = max_priority_fee_per_gas
        self.max_cost = max_cost
        self.fee_to_relayer = fee_to_relayer
        self.gateways = gateways
        self.tx_nonce = tx_nonce
        self.tx_type = tx_type
        
        

    
    def __str__(self):
        return "SubmitQuote(path={}, payer={}, gas_limit={}, regular_gas={}, gas={}, gas_from={}, max_fee_per_gas={}, max_priority_fee_per_gas={}, max_cost={}, fee_to_relayer={}, gateways={}, tx_nonce={}, tx_type={})".format(self.path, self.payer, self.gas_limit, self.regular_gas, self.gas, self.gas_from, self.max_fee_per_gas, self.max_priority_fee_per_gas, self.max_cost, self.fee_to_relayer, self.gateways, self.tx_nonce, self.tx_type)
    def __eq__(self, other):
        if self.path != other.path:
            return False
        if self.payer != other.payer:
            return False
        if self.gas_limit != other.gas_limit:
            return False
        if self.regular_gas != other.regular_gas:
            return False
        if self.gas != other.gas:
            return False
        if self.gas_from != other.gas_from:
            return False
        if self.max_fee_per_gas != other.max_fee_per_gas:
            return False
        if self.max_priority_fee_per_gas != other.max_priority_fee_per_gas:
            return False
        if self.max_cost != other.max_cost:
            return False
        if self.fee_to_relayer != other.fee_to_relayer:
            return False
        if self.gateways != other.gateways:
            return False
        if self.tx_nonce != other.tx_nonce:
            return False
        if self.tx_type != other.tx_type:
            return False
        return True

