class SeedBackupProtocol(typing.Protocol):
    """
    The words of a seed made here: revealed once, a three-word check, then forgotten (`scaas-ua`'s `SeedBackup`, CLI-SGN-11).
"""
    
    def challenge(self, ) -> typing.List[int]:
        """
        Three positions to ask (1-based).
"""
        raise NotImplementedError
    def reveal(self, ) -> SecretBytes:
        """
        The words, once (`Argument` after), as a secret read through the copy call.
"""
        raise NotImplementedError
    def verify(self, answers: SecretBytes) -> bool:
        """
        The user's three words (a secret) against the challenge.
"""
        raise NotImplementedError

class SeedBackup(SeedBackupProtocol):
    """
    The words of a seed made here: revealed once, a three-word check, then forgotten (`scaas-ua`'s `SeedBackup`, CLI-SGN-11).
"""
    
    _handle: ctypes.c_uint64
    
    def __init__(self, *args, **kwargs):
        raise ValueError("This class has no default constructor")

    def __del__(self):
        # In case of partial initialization of instances.
        handle = getattr(self, "_handle", None)
        if handle is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_scaas_sdk_fn_free_seedbackup, handle)

    def _uniffi_clone_handle(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_scaas_sdk_fn_clone_seedbackup, self._handle)

    # Used by alternative constructors or any methods which return this type.
    @classmethod
    def _uniffi_make_instance(cls, handle):
        # Lightly yucky way to bypass the usual __init__ logic
        # and just create a new instance with the required handle.
        inst = cls.__new__(cls)
        inst._handle = handle
        return inst
    def challenge(self, ) -> typing.List[int]:
        """
        Three positions to ask (1-based).
"""
        _uniffi_lowered_args = (
            self._uniffi_clone_handle(),
        )
        _uniffi_lift_return = _UniffiFfiConverterSequenceUInt32.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeSdkError
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_scaas_sdk_fn_method_seedbackup_challenge,
            *_uniffi_lowered_args,
        )
        return _uniffi_lift_return(_uniffi_ffi_result)
    def reveal(self, ) -> SecretBytes:
        """
        The words, once (`Argument` after), as a secret read through the copy call.
"""
        _uniffi_lowered_args = (
            self._uniffi_clone_handle(),
        )
        _uniffi_lift_return = _UniffiFfiConverterTypeSecretBytes.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeSdkError
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_scaas_sdk_fn_method_seedbackup_reveal,
            *_uniffi_lowered_args,
        )
        return _uniffi_lift_return(_uniffi_ffi_result)
    def verify(self, answers: SecretBytes) -> bool:
        """
        The user's three words (a secret) against the challenge.
"""
        
        _UniffiFfiConverterTypeSecretBytes.check_lower(answers)
        _uniffi_lowered_args = (
            self._uniffi_clone_handle(),
            _UniffiFfiConverterTypeSecretBytes.lower(answers),
        )
        _uniffi_lift_return = _UniffiFfiConverterBoolean.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeSdkError
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_scaas_sdk_fn_method_seedbackup_verify,
            *_uniffi_lowered_args,
        )
        return _uniffi_lift_return(_uniffi_ffi_result)





class _UniffiFfiConverterTypeSeedBackup:
    @staticmethod
    def lift(value: int) -> SeedBackup:
        return SeedBackup._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: SeedBackup):
        if not isinstance(value, SeedBackup):
            raise TypeError("Expected SeedBackup instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: SeedBackup) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> SeedBackup:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: SeedBackup, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

