class PayBody:
    """
    The `PayMeta` body by schema (pay-meta-tax spec §7.1), named.
"""
    def __init__(self):
        raise RuntimeError("PayBody cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class NONE:
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "PayBody.NONE()".format()
        def __eq__(self, other):
            if not isinstance(other, PayBody):
                return NotImplemented
            if not other.is_NONE():
                return False
            return True

    @dataclass
    class NOTE:
        
        def __init__(self, note:str):
            self.note = note
            
            
            pass

    
            
            
    
        def __str__(self):
            return "PayBody.NOTE(note={})".format(self.note)
        def __eq__(self, other):
            if not isinstance(other, PayBody):
                return NotImplemented
            if not other.is_NOTE():
                return False
            if self.note != other.note:
                return False
            return True

    @dataclass
    class CREDITOR_REF:
        
        def __init__(self, creditor_ref:str, due_date:int):
            self.creditor_ref = creditor_ref
            
            
            self.due_date = due_date
            
            
            pass

    
            
            
    
        def __str__(self):
            return "PayBody.CREDITOR_REF(creditor_ref={}, due_date={})".format(self.creditor_ref, self.due_date)
        def __eq__(self, other):
            if not isinstance(other, PayBody):
                return NotImplemented
            if not other.is_CREDITOR_REF():
                return False
            if self.creditor_ref != other.creditor_ref:
                return False
            if self.due_date != other.due_date:
                return False
            return True

    @dataclass
    class BOUND_CALL:
        
        def __init__(self, chain_id:str, target:str, call_hash:str):
            self.chain_id = chain_id
            
            
            self.target = target
            
            
            self.call_hash = call_hash
            
            
            pass

    
            
            
    
        def __str__(self):
            return "PayBody.BOUND_CALL(chain_id={}, target={}, call_hash={})".format(self.chain_id, self.target, self.call_hash)
        def __eq__(self, other):
            if not isinstance(other, PayBody):
                return NotImplemented
            if not other.is_BOUND_CALL():
                return False
            if self.chain_id != other.chain_id:
                return False
            if self.target != other.target:
                return False
            if self.call_hash != other.call_hash:
                return False
            return True

    @dataclass
    class CIPHERTEXT:
        
        def __init__(self, ciphertext:str):
            self.ciphertext = ciphertext
            
            
            pass

    
            
            
    
        def __str__(self):
            return "PayBody.CIPHERTEXT(ciphertext={})".format(self.ciphertext)
        def __eq__(self, other):
            if not isinstance(other, PayBody):
                return NotImplemented
            if not other.is_CIPHERTEXT():
                return False
            if self.ciphertext != other.ciphertext:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_NONE(self) -> bool:
        return isinstance(self, PayBody.NONE)
    def is_none(self) -> bool:
        return isinstance(self, PayBody.NONE)
    def is_NOTE(self) -> bool:
        return isinstance(self, PayBody.NOTE)
    def is_note(self) -> bool:
        return isinstance(self, PayBody.NOTE)
    def is_CREDITOR_REF(self) -> bool:
        return isinstance(self, PayBody.CREDITOR_REF)
    def is_creditor_ref(self) -> bool:
        return isinstance(self, PayBody.CREDITOR_REF)
    def is_BOUND_CALL(self) -> bool:
        return isinstance(self, PayBody.BOUND_CALL)
    def is_bound_call(self) -> bool:
        return isinstance(self, PayBody.BOUND_CALL)
    def is_CIPHERTEXT(self) -> bool:
        return isinstance(self, PayBody.CIPHERTEXT)
    def is_ciphertext(self) -> bool:
        return isinstance(self, PayBody.CIPHERTEXT)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
PayBody.NONE = type("PayBody.NONE", (PayBody.NONE, PayBody,), {})  # type: ignore
PayBody.NOTE = type("PayBody.NOTE", (PayBody.NOTE, PayBody,), {})  # type: ignore
PayBody.CREDITOR_REF = type("PayBody.CREDITOR_REF", (PayBody.CREDITOR_REF, PayBody,), {})  # type: ignore
PayBody.BOUND_CALL = type("PayBody.BOUND_CALL", (PayBody.BOUND_CALL, PayBody,), {})  # type: ignore
PayBody.CIPHERTEXT = type("PayBody.CIPHERTEXT", (PayBody.CIPHERTEXT, PayBody,), {})  # type: ignore




class _UniffiFfiConverterTypePayBody(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return PayBody.NONE(
            )
        if variant == 2:
            return PayBody.NOTE(
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 3:
            return PayBody.CREDITOR_REF(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterUInt64.read(buf),
            )
        if variant == 4:
            return PayBody.BOUND_CALL(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 5:
            return PayBody.CIPHERTEXT(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_NONE():
            return
        if value.is_NOTE():
            _UniffiFfiConverterString.check_lower(value.note)
            return
        if value.is_CREDITOR_REF():
            _UniffiFfiConverterString.check_lower(value.creditor_ref)
            _UniffiFfiConverterUInt64.check_lower(value.due_date)
            return
        if value.is_BOUND_CALL():
            _UniffiFfiConverterString.check_lower(value.chain_id)
            _UniffiFfiConverterString.check_lower(value.target)
            _UniffiFfiConverterString.check_lower(value.call_hash)
            return
        if value.is_CIPHERTEXT():
            _UniffiFfiConverterString.check_lower(value.ciphertext)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_NONE():
            buf.write_i32(1)
        if value.is_NOTE():
            buf.write_i32(2)
            _UniffiFfiConverterString.write(value.note, buf)
        if value.is_CREDITOR_REF():
            buf.write_i32(3)
            _UniffiFfiConverterString.write(value.creditor_ref, buf)
            _UniffiFfiConverterUInt64.write(value.due_date, buf)
        if value.is_BOUND_CALL():
            buf.write_i32(4)
            _UniffiFfiConverterString.write(value.chain_id, buf)
            _UniffiFfiConverterString.write(value.target, buf)
            _UniffiFfiConverterString.write(value.call_hash, buf)
        if value.is_CIPHERTEXT():
            buf.write_i32(5)
            _UniffiFfiConverterString.write(value.ciphertext, buf)



