class RescueOp:
    """
    A rescue vault's admin operation (CTR-GOV-25): `seq` the vault's shared order, from 1.
"""
    def __init__(self):
        raise RuntimeError("RescueOp cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class SET_RESCUER:
        """
        `setRescuer(seq, newRescuer)`, `new_rescuer` an address (not 0)
"""
        
        def __init__(self, seq:int, new_rescuer:str):
            self.seq = seq
            
            
            self.new_rescuer = new_rescuer
            
            
            pass

    
            
            
    
        def __str__(self):
            return "RescueOp.SET_RESCUER(seq={}, new_rescuer={})".format(self.seq, self.new_rescuer)
        def __eq__(self, other):
            if not isinstance(other, RescueOp):
                return NotImplemented
            if not other.is_SET_RESCUER():
                return False
            if self.seq != other.seq:
                return False
            if self.new_rescuer != other.new_rescuer:
                return False
            return True

    @dataclass
    class ROTATE_ADMIN:
        """
        `rotateAdmin(seq, newAdmin)`, `new_admin` a native UA (not 0)
"""
        
        def __init__(self, seq:int, new_admin:str):
            self.seq = seq
            
            
            self.new_admin = new_admin
            
            
            pass

    
            
            
    
        def __str__(self):
            return "RescueOp.ROTATE_ADMIN(seq={}, new_admin={})".format(self.seq, self.new_admin)
        def __eq__(self, other):
            if not isinstance(other, RescueOp):
                return NotImplemented
            if not other.is_ROTATE_ADMIN():
                return False
            if self.seq != other.seq:
                return False
            if self.new_admin != other.new_admin:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_SET_RESCUER(self) -> bool:
        return isinstance(self, RescueOp.SET_RESCUER)
    def is_set_rescuer(self) -> bool:
        return isinstance(self, RescueOp.SET_RESCUER)
    def is_ROTATE_ADMIN(self) -> bool:
        return isinstance(self, RescueOp.ROTATE_ADMIN)
    def is_rotate_admin(self) -> bool:
        return isinstance(self, RescueOp.ROTATE_ADMIN)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
RescueOp.SET_RESCUER = type("RescueOp.SET_RESCUER", (RescueOp.SET_RESCUER, RescueOp,), {})  # type: ignore
RescueOp.ROTATE_ADMIN = type("RescueOp.ROTATE_ADMIN", (RescueOp.ROTATE_ADMIN, RescueOp,), {})  # type: ignore




class _UniffiFfiConverterTypeRescueOp(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return RescueOp.SET_RESCUER(
                _UniffiFfiConverterUInt64.read(buf),
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 2:
            return RescueOp.ROTATE_ADMIN(
                _UniffiFfiConverterUInt64.read(buf),
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_SET_RESCUER():
            _UniffiFfiConverterUInt64.check_lower(value.seq)
            _UniffiFfiConverterString.check_lower(value.new_rescuer)
            return
        if value.is_ROTATE_ADMIN():
            _UniffiFfiConverterUInt64.check_lower(value.seq)
            _UniffiFfiConverterString.check_lower(value.new_admin)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_SET_RESCUER():
            buf.write_i32(1)
            _UniffiFfiConverterUInt64.write(value.seq, buf)
            _UniffiFfiConverterString.write(value.new_rescuer, buf)
        if value.is_ROTATE_ADMIN():
            buf.write_i32(2)
            _UniffiFfiConverterUInt64.write(value.seq, buf)
            _UniffiFfiConverterString.write(value.new_admin, buf)



