class Presence(enum.Enum):
    """
    Whether the platform asks for the user before it gives the item.
"""
    
    NONE = 0
    
    REQUIRED = 1
    


class _UniffiFfiConverterTypePresence(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Presence.NONE
        if variant == 2:
            return Presence.REQUIRED
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == Presence.NONE:
            return
        if value == Presence.REQUIRED:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == Presence.NONE:
            buf.write_i32(1)
        if value == Presence.REQUIRED:
            buf.write_i32(2)



