@dataclass
class TradeOrder:
    """
    A trade order (`TradeOrder`'s named fields, CTR-DEX-15): sold `amount` of `sell_token` for at least `receive_amount` of
    `receive_token`, each settlement at least `min_fill` unless it closes the order.
"""
    def __init__(self, *, signer:KeyRef, chain:str, sell_token:str, dex:str, receive_token:str, amount:str, receive_amount:str, min_fill:str, fee:str, relayer:str, destination:typing.Optional[str], flags:int, batch:str, nonce:typing.Optional[str], valid_until:int):
        self.signer = signer
        self.chain = chain
        self.sell_token = sell_token
        self.dex = dex
        self.receive_token = receive_token
        self.amount = amount
        self.receive_amount = receive_amount
        self.min_fill = min_fill
        self.fee = fee
        self.relayer = relayer
        self.destination = destination
        self.flags = flags
        self.batch = batch
        self.nonce = nonce
        self.valid_until = valid_until
        
        

    
    def __str__(self):
        return "TradeOrder(signer={}, chain={}, sell_token={}, dex={}, receive_token={}, amount={}, receive_amount={}, min_fill={}, fee={}, relayer={}, destination={}, flags={}, batch={}, nonce={}, valid_until={})".format(self.signer, self.chain, self.sell_token, self.dex, self.receive_token, self.amount, self.receive_amount, self.min_fill, self.fee, self.relayer, self.destination, self.flags, self.batch, self.nonce, self.valid_until)
    def __eq__(self, other):
        if self.signer != other.signer:
            return False
        if self.chain != other.chain:
            return False
        if self.sell_token != other.sell_token:
            return False
        if self.dex != other.dex:
            return False
        if self.receive_token != other.receive_token:
            return False
        if self.amount != other.amount:
            return False
        if self.receive_amount != other.receive_amount:
            return False
        if self.min_fill != other.min_fill:
            return False
        if self.fee != other.fee:
            return False
        if self.relayer != other.relayer:
            return False
        if self.destination != other.destination:
            return False
        if self.flags != other.flags:
            return False
        if self.batch != other.batch:
            return False
        if self.nonce != other.nonce:
            return False
        if self.valid_until != other.valid_until:
            return False
        return True

