@dataclass
class ZetherWrapShield:
    """
    `zether_wrap_shield` (`WrapShield` on a Zether token): wrap `amount_in` of `underlying` and shield it to `to_ua`.
"""
    def __init__(self, *, signer:KeyRef, chain:str, token:str, batch:str, underlying:str, amount_in:str, to_ua:str, envelope:Envelope):
        self.signer = signer
        self.chain = chain
        self.token = token
        self.batch = batch
        self.underlying = underlying
        self.amount_in = amount_in
        self.to_ua = to_ua
        self.envelope = envelope
        
        

    
    def __str__(self):
        return "ZetherWrapShield(signer={}, chain={}, token={}, batch={}, underlying={}, amount_in={}, to_ua={}, envelope={})".format(self.signer, self.chain, self.token, self.batch, self.underlying, self.amount_in, self.to_ua, self.envelope)
    def __eq__(self, other):
        if self.signer != other.signer:
            return False
        if self.chain != other.chain:
            return False
        if self.token != other.token:
            return False
        if self.batch != other.batch:
            return False
        if self.underlying != other.underlying:
            return False
        if self.amount_in != other.amount_in:
            return False
        if self.to_ua != other.to_ua:
            return False
        if self.envelope != other.envelope:
            return False
        return True

