class InFlight(enum.Enum):
    """
    What is known of an operation in flight (spec §13.5): none of it ends the operation.
"""
    
    SIGNED = 0
    """
    signed and written, not sent yet
"""
    
    QUEUED = 1
    """
    a gateway queued it
"""
    
    GIVEN_UP_BY_EVERY_NODE = 2
    """
    every gateway it went to refused it or could not be reached (one node's `dead` covers its own sends only)
"""
    
    SENT = 3
    """
    the self-relay transaction was accepted by an endpoint
"""
    
    BROADCAST_REJECTED = 4
    """
    no endpoint accepted the self-relay transaction (`BroadcastRejected`, an outcome, never final)
"""
    
    TX_INCLUDED = 5
    """
    the self-relay transaction is in a block, not final, or final and successful while the event is not read yet
"""
    
    TX_FINAL_FAILED = 6
    """
    the self-relay transaction is final and failed: the signed operation may still land by another relayer
"""
    
    TX_REPLACED = 7
    """
    the self-relay transaction was replaced
"""
    
    SIM_REFUSED = 8
    """
    the signed operation's simulation from the payer reverted, failed or needed more gas than the confirmed quote: not sent
    by this SDK (owner 2026-11-19, ruling A). It is signed and may still land by another relayer until its nonce is spent or
    `validUntil` passes; `resend` tries again, a cancel of the lane's nonce ends it.
"""
    


class _UniffiFfiConverterTypeInFlight(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return InFlight.SIGNED
        if variant == 2:
            return InFlight.QUEUED
        if variant == 3:
            return InFlight.GIVEN_UP_BY_EVERY_NODE
        if variant == 4:
            return InFlight.SENT
        if variant == 5:
            return InFlight.BROADCAST_REJECTED
        if variant == 6:
            return InFlight.TX_INCLUDED
        if variant == 7:
            return InFlight.TX_FINAL_FAILED
        if variant == 8:
            return InFlight.TX_REPLACED
        if variant == 9:
            return InFlight.SIM_REFUSED
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == InFlight.SIGNED:
            return
        if value == InFlight.QUEUED:
            return
        if value == InFlight.GIVEN_UP_BY_EVERY_NODE:
            return
        if value == InFlight.SENT:
            return
        if value == InFlight.BROADCAST_REJECTED:
            return
        if value == InFlight.TX_INCLUDED:
            return
        if value == InFlight.TX_FINAL_FAILED:
            return
        if value == InFlight.TX_REPLACED:
            return
        if value == InFlight.SIM_REFUSED:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == InFlight.SIGNED:
            buf.write_i32(1)
        if value == InFlight.QUEUED:
            buf.write_i32(2)
        if value == InFlight.GIVEN_UP_BY_EVERY_NODE:
            buf.write_i32(3)
        if value == InFlight.SENT:
            buf.write_i32(4)
        if value == InFlight.BROADCAST_REJECTED:
            buf.write_i32(5)
        if value == InFlight.TX_INCLUDED:
            buf.write_i32(6)
        if value == InFlight.TX_FINAL_FAILED:
            buf.write_i32(7)
        if value == InFlight.TX_REPLACED:
            buf.write_i32(8)
        if value == InFlight.SIM_REFUSED:
            buf.write_i32(9)








class OpState:
    """
    An operation's state (spec §13.5, CLI-SDK-18): terminal only on a chain fact from a decisive read at the profile's final
    block.
"""
    def __init__(self):
        raise RuntimeError("OpState cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    @dataclass
    class LANDED:
        """
        the executed event of the operation's digest at or below the final block
"""
        
        def __init__(self, block:int, hash:str):
            self.block = block
            
            
            self.hash = hash
            
            
            pass

    
            
            
    
        def __str__(self):
            return "OpState.LANDED(block={}, hash={})".format(self.block, self.hash)
        def __eq__(self, other):
            if not isinstance(other, OpState):
                return NotImplemented
            if not other.is_LANDED():
                return False
            if self.block != other.block:
                return False
            if self.hash != other.hash:
                return False
            return True

    @dataclass
    class CONSUMED:
        """
        the lane's nonce spent at the final block without that event; a replaced native send
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "OpState.CONSUMED()".format()
        def __eq__(self, other):
            if not isinstance(other, OpState):
                return NotImplemented
            if not other.is_CONSUMED():
                return False
            return True

    @dataclass
    class REVERTED:
        """
        an EVM native send final at or below the final block and reverted (owner 2026-11-18, ruling 4; the node's `reverted`)
"""
        
        def __init__(self, block:int, hash:str):
            self.block = block
            
            
            self.hash = hash
            
            
            pass

    
            
            
    
        def __str__(self):
            return "OpState.REVERTED(block={}, hash={})".format(self.block, self.hash)
        def __eq__(self, other):
            if not isinstance(other, OpState):
                return NotImplemented
            if not other.is_REVERTED():
                return False
            if self.block != other.block:
                return False
            if self.hash != other.hash:
                return False
            return True

    @dataclass
    class EXPIRED:
        """
        `validUntil` below the final block's timestamp while the nonce is unspent
"""
        
        def __init__(self, ):
            pass

    
            
            
    
        def __str__(self):
            return "OpState.EXPIRED()".format()
        def __eq__(self, other):
            if not isinstance(other, OpState):
                return NotImplemented
            if not other.is_EXPIRED():
                return False
            return True

    @dataclass
    class IN_FLIGHT:
        """
        anything else, with what is known (never an end)
"""
        
        def __init__(self, detail:InFlight):
            self.detail = detail
            
            
            pass

    
            
            
    
        def __str__(self):
            return "OpState.IN_FLIGHT(detail={})".format(self.detail)
        def __eq__(self, other):
            if not isinstance(other, OpState):
                return NotImplemented
            if not other.is_IN_FLIGHT():
                return False
            if self.detail != other.detail:
                return False
            return True

    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_LANDED(self) -> bool:
        return isinstance(self, OpState.LANDED)
    def is_landed(self) -> bool:
        return isinstance(self, OpState.LANDED)
    def is_CONSUMED(self) -> bool:
        return isinstance(self, OpState.CONSUMED)
    def is_consumed(self) -> bool:
        return isinstance(self, OpState.CONSUMED)
    def is_REVERTED(self) -> bool:
        return isinstance(self, OpState.REVERTED)
    def is_reverted(self) -> bool:
        return isinstance(self, OpState.REVERTED)
    def is_EXPIRED(self) -> bool:
        return isinstance(self, OpState.EXPIRED)
    def is_expired(self) -> bool:
        return isinstance(self, OpState.EXPIRED)
    def is_IN_FLIGHT(self) -> bool:
        return isinstance(self, OpState.IN_FLIGHT)
    def is_in_flight(self) -> bool:
        return isinstance(self, OpState.IN_FLIGHT)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
OpState.LANDED = type("OpState.LANDED", (OpState.LANDED, OpState,), {})  # type: ignore
OpState.CONSUMED = type("OpState.CONSUMED", (OpState.CONSUMED, OpState,), {})  # type: ignore
OpState.REVERTED = type("OpState.REVERTED", (OpState.REVERTED, OpState,), {})  # type: ignore
OpState.EXPIRED = type("OpState.EXPIRED", (OpState.EXPIRED, OpState,), {})  # type: ignore
OpState.IN_FLIGHT = type("OpState.IN_FLIGHT", (OpState.IN_FLIGHT, OpState,), {})  # type: ignore




class _UniffiFfiConverterTypeOpState(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return OpState.LANDED(
                _UniffiFfiConverterUInt64.read(buf),
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 2:
            return OpState.CONSUMED(
            )
        if variant == 3:
            return OpState.REVERTED(
                _UniffiFfiConverterUInt64.read(buf),
                _UniffiFfiConverterString.read(buf),
            )
        if variant == 4:
            return OpState.EXPIRED(
            )
        if variant == 5:
            return OpState.IN_FLIGHT(
                _UniffiFfiConverterTypeInFlight.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_LANDED():
            _UniffiFfiConverterUInt64.check_lower(value.block)
            _UniffiFfiConverterString.check_lower(value.hash)
            return
        if value.is_CONSUMED():
            return
        if value.is_REVERTED():
            _UniffiFfiConverterUInt64.check_lower(value.block)
            _UniffiFfiConverterString.check_lower(value.hash)
            return
        if value.is_EXPIRED():
            return
        if value.is_IN_FLIGHT():
            _UniffiFfiConverterTypeInFlight.check_lower(value.detail)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_LANDED():
            buf.write_i32(1)
            _UniffiFfiConverterUInt64.write(value.block, buf)
            _UniffiFfiConverterString.write(value.hash, buf)
        if value.is_CONSUMED():
            buf.write_i32(2)
        if value.is_REVERTED():
            buf.write_i32(3)
            _UniffiFfiConverterUInt64.write(value.block, buf)
            _UniffiFfiConverterString.write(value.hash, buf)
        if value.is_EXPIRED():
            buf.write_i32(4)
        if value.is_IN_FLIGHT():
            buf.write_i32(5)
            _UniffiFfiConverterTypeInFlight.write(value.detail, buf)








