class _UniffiFfiConverterTypePrepared:
    @staticmethod
    def lift(value: int) -> Prepared:
        return Prepared._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Prepared):
        if not isinstance(value, Prepared):
            raise TypeError("Expected Prepared instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Prepared) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Prepared:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Prepared, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

class _UniffiFfiConverterSequenceTypeRegistryWrite(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeRegistryWrite.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeRegistryWrite.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeRegistryWrite.read(buf) for i in range(count)
        ]


