class _UniffiFfiConverterTypeAdmin:
    @staticmethod
    def lift(value: int) -> Admin:
        return Admin._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Admin):
        if not isinstance(value, Admin):
            raise TypeError("Expected Admin instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Admin) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Admin:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Admin, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))


