class _UniffiFfiConverterTypeOp:
    @staticmethod
    def lift(value: int) -> Op:
        return Op._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Op):
        if not isinstance(value, Op):
            raise TypeError("Expected Op instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Op) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Op:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Op, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

class _UniffiFfiConverterOptionalTypeEvent(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeEvent.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeEvent.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeEvent.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")


class SubscriptionProtocol(typing.Protocol):
    """
    A subscription to the SDK's events (spec §14): a bounded queue, `Lagged { missed }` for a slow reader.
"""
    
    async def next(self, timeout_ms: int) -> typing.Optional[Event]:
        """
        The next event, or `None` within `timeout_ms`.
"""
        raise NotImplementedError

class Subscription(SubscriptionProtocol):
    """
    A subscription to the SDK's events (spec §14): a bounded queue, `Lagged { missed }` for a slow reader.
"""
    
    _handle: ctypes.c_uint64
    
    def __init__(self, *args, **kwargs):
        raise ValueError("This class has no default constructor")

    def __del__(self):
        # In case of partial initialization of instances.
        handle = getattr(self, "_handle", None)
        if handle is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_scaas_sdk_fn_free_subscription, handle)

    def _uniffi_clone_handle(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_scaas_sdk_fn_clone_subscription, self._handle)

    # Used by alternative constructors or any methods which return this type.
    @classmethod
    def _uniffi_make_instance(cls, handle):
        # Lightly yucky way to bypass the usual __init__ logic
        # and just create a new instance with the required handle.
        inst = cls.__new__(cls)
        inst._handle = handle
        return inst
    async def next(self, timeout_ms: int) -> typing.Optional[Event]:
        """
        The next event, or `None` within `timeout_ms`.
"""
        
        _UniffiFfiConverterUInt64.check_lower(timeout_ms)
        _uniffi_lowered_args = (
            self._uniffi_clone_handle(),
            _UniffiFfiConverterUInt64.lower(timeout_ms),
        )
        _uniffi_lift_return = _UniffiFfiConverterOptionalTypeEvent.lift
        _uniffi_error_converter = _UniffiFfiConverterTypeSdkError
        return await _uniffi_rust_call_async(
            _UniffiLib.uniffi_scaas_sdk_fn_method_subscription_next(*_uniffi_lowered_args),
            _UniffiLib.ffi_scaas_sdk_rust_future_poll_rust_buffer,
            _UniffiLib.ffi_scaas_sdk_rust_future_complete_rust_buffer,
            _UniffiLib.ffi_scaas_sdk_rust_future_free_rust_buffer,
            _uniffi_lift_return,
            _uniffi_error_converter,
        )





class _UniffiFfiConverterTypeSubscription:
    @staticmethod
    def lift(value: int) -> Subscription:
        return Subscription._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Subscription):
        if not isinstance(value, Subscription):
            raise TypeError("Expected Subscription instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Subscription) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Subscription:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Subscription, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

class _UniffiFfiConverterSequenceTypeSeedInfo(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeSeedInfo.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeSeedInfo.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeSeedInfo.read(buf) for i in range(count)
        ]


