class _UniffiFfiConverterTypeVault:
    @staticmethod
    def lift(value: int) -> Vault:
        return Vault._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Vault):
        if not isinstance(value, Vault):
            raise TypeError("Expected Vault instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Vault) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Vault:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Vault, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

class _UniffiFfiConverterSequenceTypeTokenInfo(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeTokenInfo.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeTokenInfo.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeTokenInfo.read(buf) for i in range(count)
        ]


