class _UniffiFfiConverterTypeWallet:
    @staticmethod
    def lift(value: int) -> Wallet:
        return Wallet._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Wallet):
        if not isinstance(value, Wallet):
            raise TypeError("Expected Wallet instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Wallet) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Wallet:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Wallet, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))


class SdkProtocol(typing.Protocol):
    """
    The SDK (spec §4): the module accessors, events, watching.
"""
    
    def account(self, ) -> Account:
        """
        The account module (spec §7).
"""
        raise NotImplementedError
    def admin(self, ) -> Admin:
        """
        The admin module (spec §11).
"""
        raise NotImplementedError
    def confidential(self, ) -> Confidential:
        """
        The confidential module (spec §9).
"""
        raise NotImplementedError
    def dex(self, ) -> Dex:
        """
        The DEX module (spec §10).
"""
        raise NotImplementedError
    def limits(self, ) -> Limits:
        """
        The limits in force.
"""
        raise NotImplementedError
    def op(self, ) -> Op:
        """
        The operations module (spec §13).
"""
        raise NotImplementedError
    async def state_rev(self, ) -> int:
        raise NotImplementedError
    def subscribe(self, ) -> Subscription:
        """
        A subscription to the SDK's events (spec §14).
"""
        raise NotImplementedError
    def vault(self, ) -> Vault:
        """
        The seed module (spec §6).
"""
        raise NotImplementedError
    def wallet(self, ) -> Wallet:
        """
        The wallet module (spec §8).
"""
        raise NotImplementedError
    async def watch(self, account: str,chains: typing.List[str]) -> None:
        raise NotImplementedError

