class _UniffiFfiConverterTypeSdk:
    @staticmethod
    def lift(value: int) -> Sdk:
        return Sdk._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: Sdk):
        if not isinstance(value, Sdk):
            raise TypeError("Expected Sdk instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: Sdk) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> Sdk:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: Sdk, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))

class _UniffiFfiConverterSequenceTypeAccountRow(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiFfiConverterTypeAccountRow.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiFfiConverterTypeAccountRow.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiFfiConverterTypeAccountRow.read(buf) for i in range(count)
        ]

class _UniffiFfiConverterOptionalTypeForeignAuthenticator(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiFfiConverterTypeForeignAuthenticator.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiFfiConverterTypeForeignAuthenticator.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiFfiConverterTypeForeignAuthenticator.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")
